// Colours: the brand palettes of the website – the same ground / ink pairs and the same bullseye picker as
// Otázky na tělo. <html data-palette="clay-pink|pink-clay|blue-cream|cream-blue|cream-clay"> (absent = the
// device decides: cream-clay in light mode, clay-pink in dark mode) + data-theme="light|dark" from the
// palette, so the few [data-theme="dark"] component rules follow. The colours live in css/palettes.css
// (generated by zvonec/palettes.mjs, every pair verified for contrast).
// Remembered in localStorage (zvonec-palette). A link may set it too (for sharing – the choice is kept):
// ?paleta=hlina-ruzova|ruzova-hlina|modra-krem|krem-modra|krem-hlina|zarizeni (the Otázky slugs; the ids
// work too), and the older ?rezim=svetly|tmavy|zarizeni (Světlý = Krém a hlína, Tmavý = Hlína a růžová).
// A classic script in <head> (not a module): it applies the choice before the first paint, so the page does
// not flash. The picker is ui/palette-picker.js (built with h(), mounted by app.js); other code (Můj účet)
// uses window.zvonecAppearance: { palettes, palette(), setPalette(id) } and the 'zvonec:appearance' event.
(function () {
  var KEY = 'zvonec-palette';
  // id, label (Czech, as in Otázky), scheme, the Czech slug for links – the order is the picker's grid
  var PALETTES = [
    ['clay-pink', 'Hlína a růžová', 'dark', 'hlina-ruzova'],
    ['pink-clay', 'Růžová a hlína', 'light', 'ruzova-hlina'],
    ['blue-cream', 'Modrá a krém', 'dark', 'modra-krem'],
    ['cream-blue', 'Krém a modrá', 'light', 'krem-modra'],
    ['cream-clay', 'Krém a hlína', 'light', 'krem-hlina'],
  ];
  var BY_THEME = { light: 'cream-clay', dark: 'clay-pink' };
  var root = document.documentElement;

  function find(id) {
    for (var i = 0; i < PALETTES.length; i++) if (PALETTES[i][0] === id || PALETTES[i][3] === id) return PALETTES[i];
    return null;
  }
  function read(key) { try { return localStorage.getItem(key); } catch (error) { return null; } }
  function write(key, value) {
    try { if (value) localStorage.setItem(key, value); else localStorage.removeItem(key); } catch (error) { /* works without storage, just not remembered */ }
  }

  // once: the mode of the redesign (zvonec-theme light/dark) becomes its palette; a palette of the old
  // Zvonec that is no longer offered (the green ones, pink-blue) becomes the light or dark default
  var oldTheme = read('zvonec-theme');
  if (oldTheme) {
    if (!read(KEY) && BY_THEME[oldTheme]) write(KEY, BY_THEME[oldTheme]);
    write('zvonec-theme', null);
  }
  var stored = read(KEY);
  if (stored && !find(stored)) write(KEY, { 'green-cream': 'clay-pink', 'green-pink': 'clay-pink' }[stored] || 'cream-clay');
  write('zvonec-look', null);

  // a link may carry the choice
  var query = {};
  try { query = Object.fromEntries(new URLSearchParams(location.search)); } catch (error) { /* old browser: no link choice */ }
  if (query.paleta !== undefined) {
    if (query.paleta === 'zarizeni') write(KEY, null);
    else if (find(query.paleta)) write(KEY, find(query.paleta)[0]);
  } else if (query.rezim !== undefined) {
    var fromMode = { svetly: BY_THEME.light, tmavy: BY_THEME.dark, zarizeni: '' }[query.rezim];
    if (fromMode !== undefined) write(KEY, fromMode);
  }

  function apply(id) {
    var p = find(id);
    if (p) { root.setAttribute('data-palette', p[0]); root.setAttribute('data-theme', p[2]); }
    else { root.removeAttribute('data-palette'); root.removeAttribute('data-theme'); }
  }
  apply(read(KEY));

  function syncThemeColor() {
    var meta = document.querySelector('meta[name="theme-color"]');
    var color = getComputedStyle(root).getPropertyValue('--surface-chrome').trim();
    if (meta && color) meta.setAttribute('content', color);
  }

  var api = {
    palettes: PALETTES.map(function (p) { return { id: p[0], label: p[1], scheme: p[2] }; }),
    /** the chosen palette id, '' = the device decides */
    palette: function () { return root.getAttribute('data-palette') || ''; },
    setPalette: function (id) {
      var p = find(id);
      apply(p ? p[0] : '');
      write(KEY, p ? p[0] : '');
      syncThemeColor();
      try { document.dispatchEvent(new CustomEvent('zvonec:appearance', { detail: { palette: api.palette() } })); } catch (error) { /* no listeners then */ }
    },
  };
  window.zvonecAppearance = api;

  document.addEventListener('DOMContentLoaded', function () {
    syncThemeColor();
    if (window.matchMedia) {
      var scheme = window.matchMedia('(prefers-color-scheme: dark)');
      if (scheme.addEventListener) scheme.addEventListener('change', syncThemeColor);
    }
  });
})();
